package com.mssp0.appletv;
import android.app.*; import android.os.*; import android.content.*; import android.content.pm.*; import android.graphics.Color; import android.graphics.Typeface; import android.graphics.drawable.GradientDrawable; import android.provider.Settings; import android.view.*; import android.widget.*; import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root, dock; TextView clock; int bg=Color.rgb(13,19,32);
 GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(-1);t.setTextSize(size);t.setGravity(17);return t;}
 public void onCreate(Bundle b){super.onCreate(b);home();}
 void base(String heading){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(42,24,42,25);root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff182f4d,bg,0xff090c15}));setContentView(root);TextView h=text(heading,32);h.setGravity(3);h.setTypeface(null,Typeface.BOLD);root.addView(h,new LinearLayout.LayoutParams(-1,72));}
 void tile(String title,String pkg, boolean settings){TextView t=text(title,22);t.setTypeface(null,Typeface.BOLD);t.setFocusable(true);t.setBackground(shape(0xff263a57,22));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,125,1);p.setMargins(7,0,7,0);dock.addView(t,p);t.setOnFocusChangeListener((v,f)->{t.setBackground(shape(f?0xff638ddd:0xff263a57,22));t.setScaleX(f?1.06f:1f);t.setScaleY(f?1.06f:1f);});t.setOnClickListener(v->{if(settings){startActivity(new Intent(Settings.ACTION_SETTINGS));return;}Intent i=getPackageManager().getLeanbackLaunchIntentForPackage(pkg);if(i==null)i=getPackageManager().getLaunchIntentForPackage(pkg);if(i!=null)startActivity(i);else Toast.makeText(this,title+" не найдено",Toast.LENGTH_SHORT).show();});}
 void home(){base("Apple TV Style");clock=text("",21);clock.setGravity(5);root.addView(clock);updateClock();TextView welcome=text("С возвращением",34);welcome.setGravity(3);LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(-1,0,1);root.addView(welcome,wp);dock=new LinearLayout(this);root.addView(dock);tile("YouTube","com.google.android.youtube.tv",false);tile("Twitch","tv.twitch.android.app",false);tile("Настройки","",true);tile("Happ Proxy","com.happproxy",false);TextView apps=text("Все приложения  →",20);apps.setFocusable(true);apps.setPadding(10,28,10,15);root.addView(apps);apps.setOnClickListener(v->allApps());dock.getChildAt(0).requestFocus();}
 void updateClock(){if(clock!=null)clock.setText(new java.text.SimpleDateFormat("dd MMMM  •  HH:mm",new Locale("ru")).format(new Date()));new Handler().postDelayed(()->{if(!isFinishing())updateClock();},60000);}
 void allApps(){base("Все приложения");ScrollView sc=new ScrollView(this);root.addView(sc);LinearLayout list=new LinearLayout(this);list.setOrientation(1);sc.addView(list);Intent q=new Intent(Intent.ACTION_MAIN);q.addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER);List<ResolveInfo> found=getPackageManager().queryIntentActivities(q,0);Collections.sort(found,new ResolveInfo.DisplayNameComparator(getPackageManager()));for(ResolveInfo r:found){TextView t=text(r.loadLabel(getPackageManager()).toString(),22);t.setGravity(3);t.setPadding(22,16,10,16);t.setFocusable(true);list.addView(t);t.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_MAIN);i.setClassName(r.activityInfo.packageName,r.activityInfo.name);startActivity(i);});}if(list.getChildCount()>0)list.getChildAt(0).requestFocus();}
 @Override public void onBackPressed(){home();}
}